INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z5-q70','nism-10b-z5','A monthly SIP of ₹6,000 earns 10% p.a. (monthly compounding, instalments at month-end) for 15 years. The maturity value is approximately:','["₹21,13,799","₹11,88,000","₹10,80,000","₹24,86,822"]',3,'FV = P × [((1 + r)^m − 1) ÷ r], r = i ÷ 12.',70) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z5-q71','nism-10b-z5','Monthly expenses are ₹35,000 today. With inflation of 5% p.a., the monthly expense after 15 years will be approximately:','["₹70,000","₹72,762","₹61,250","₹65,998"]',1,'Future expense = today''s expense × (1 + inflation)^n.',71) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
